use std::sync::{Arc, Mutex}; use std::thread; use std::time::Duration; use remdb::pubsub::{PubSub, PubSubConfig, UdpMode}; use crate::logger::{Logger, LogLevel}; // 客户端状态 pub struct PubSubClient { pubsub: Arc<Mutex<PubSub>>, running: Arc<Mutex<bool>>, connected: Arc<Mutex<bool>>, last_heartbeat: Arc<Mutex<std::time::Instant>>, logger: Logger, } impl PubSubClient { // 创建新的客户端实例 pub fn new() -> Self { let logger = Logger::new("PubSubClient", None); logger.info("Initializing PubSub client..."); let config = PubSubConfig { udp_mode: UdpMode::Broadcast, multicast_addr: None, port: 5555, max_topics: 32, max_subscribers_per_topic: 16, buffer_size: 4096, enable_nack: true, retransmit_timeout: Duration::from_millis(100), max_retransmits: 3, heartbeat_interval: Duration::from_secs(5), frame_pool_size: 128, }; logger.debug(&format!("Creating PubSub instance with config: {:?}", config)); let mut pubsub = PubSub::new(config).expect("Failed to create PubSub instance"); pubsub.init().expect("Failed to initialize PubSub"); logger.info("PubSub instance initialized successfully"); Self { pubsub: Arc::new(Mutex::new(pubsub)), running: Arc::new(Mutex::new(true)), connected: Arc::new(Mutex::new(false)), last_heartbeat: Arc::new(Mutex::new(std::time::Instant::now())), logger, } } // 启动客户端 pub fn start(&mut self) { self.logger.info("Starting PubSub client..."); let pubsub_clone = self.pubsub.clone(); let running_clone = self.running.clone(); let connected_clone = self.connected.clone(); let last_heartbeat_clone = self.last_heartbeat.clone(); let logger_clone = self.logger.clone(); // 定义心跳回调 let heartbeat_callback = move |_topic_id: u16, data: &[u8]| -> bool { if data == b"heartbeat" { *last_heartbeat_clone.lock().unwrap() = std::time::Instant::now(); *connected_clone.lock().unwrap() = true; logger_clone.info("Received heartbeat from server"); } true }; // 订阅心跳主题 logger_clone.debug("Subscribing to heartbeat topic (ID: 0)..."); match pubsub_clone.lock().unwrap().subscribe(0, heartbeat_callback) { Ok(subscription_id) => logger_clone.debug(&format!("Successfully subscribed to heartbeat topic with ID: {}", subscription_id)), Err(e) => logger_clone.error(&format!("Failed to subscribe to heartbeat topic: {:?}", e)), } // 启动连接监控线程 let connected_clone2 = self.connected.clone(); let last_heartbeat_clone2 = self.last_heartbeat.clone(); let logger_clone2 = self.logger.clone(); let _monitor_thread = thread::spawn(move || { logger_clone2.info("Started connection monitor thread"); while *running_clone.lock().unwrap() { let last_hb = last_heartbeat_clone2.lock().unwrap().clone(); if last_hb.elapsed() > Duration::from_secs(15) { // 超过15秒没有收到心跳，标记为断开连接 if *connected_clone2.lock().unwrap() { *connected_clone2.lock().unwrap() = false; logger_clone2.warning("Connection lost: no heartbeat received for 15 seconds"); // 尝试重新连接 logger_clone2.info("Attempting to reconnect..."); // 这里可以添加重新连接逻辑 } } thread::sleep(Duration::from_secs(1)); } logger_clone2.info("Connection monitor thread stopped"); }); self.logger.info("PubSub test client started successfully!"); self.logger.info("Listening for messages on UDP port 5555"); self.logger.info("Monitoring server heartbeat..."); } // 订阅主题 pub fn subscribe(&mut self, topic_id: u16, callback: fn(u16, &[u8]) -> bool) -> usize { self.logger.debug(&format!("Subscribing to topic ID: {}", topic_id)); match self.pubsub.lock().unwrap().subscribe(topic_id, callback) { Ok(subscription_id) => { self.logger.info(&format!("Successfully subscribed to topic ID: {} with subscription ID: {}", topic_id, subscription_id)); subscription_id }, Err(e) => { self.logger.error(&format!("Failed to subscribe to topic ID {}: {:?}", topic_id, e)); panic!("Failed to subscribe"); } } } // 取消订阅 pub fn unsubscribe(&mut self, subscription_id: usize) { self.logger.debug(&format!("Unsubscribing from subscription ID: {}", subscription_id)); match self.pubsub.lock().unwrap().unsubscribe(subscription_id) { Ok(_) => self.logger.info(&format!("Successfully unsubscribed from subscription ID: {}", subscription_id)), Err(e) => self.logger.error(&format!("Failed to unsubscribe from subscription ID {}: {:?}", subscription_id, e)), } } // 发布消息 pub fn publish(&mut self, topic_id: u16, data: &[u8]) { self.logger.debug(&format!("Publishing message to topic ID: {}, data: {:?}", topic_id, String::from_utf8_lossy(data))); match self.pubsub.lock().unwrap().publish(topic_id, data) { Ok(_) => self.logger.debug(&format!("Successfully published message to topic ID: {}", topic_id)), Err(e) => self.logger.error(&format!("Failed to publish message to topic ID {}: {:?}", topic_id, e)), } } // 检查连接状态 pub fn is_connected(&self) -> bool { let connected = *self.connected.lock().unwrap(); self.logger.debug(&format!("Connection status: {}", connected)); connected } // 停止客户端 pub fn stop(&mut self) { self.logger.info("Stopping PubSub client..."); *self.running.lock().unwrap() = false; match self.pubsub.lock().unwrap().shutdown() { Ok(_) => self.logger.info("PubSub instance shutdown successfully"), Err(e) => self.logger.error(&format!("Failed to shutdown PubSub: {:?}", e)), } self.logger.info("PubSub test client stopped!"); } } // 主函数，用于独立运行客户端 fn main() { let mut client = PubSubClient::new(); client.start(); // 定义测试回调 let test_callback = |topic_id: u16, data: &[u8]| -> bool { println!("Received data on topic {}: {:?}", topic_id, String::from_utf8_lossy(data)); true }; // 订阅所有主题 client.subscribe(0xFFFF, test_callback); // 运行2分钟后自动停止 thread::sleep(Duration::from_secs(120)); client.stop(); }